from typing import List

class Solution:
    def arrayNesting(self, A: List[int]) -> int:
        visited = [False] * len(A)
        max_length = 0

        for i in range(len(A)):
            if visited[i]:
                continue

            current = i
            length = 0

            while not visited[current]:
                visited[current] = True
                current = A[current]
                length += 1

            if length > max_length:
                max_length = length

        return max_length
